torch::Tensor conv_transpose2d_cuda(torch::Tensor x) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    conv_transpose2d_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), x.data_ptr<float>(), 
